167→test("attribution is the response's own binding, not the command text", () => {
168→  // The command may ask by name, or be a search returning several hits; only
169→  // the response says which asset the content came from. And a command that
170→  // merely mentions an id (`grep skl-hidden …`) returns content that names
171→  // no asset at all.
172→  const requests = [req([
173→    { role: "assistant", content: null, tool_calls: [{ id: "c1", function: { name: "Bash", arguments: JSON.stringify({ command: "curl .../skill/get-by-name -d '{\"skill_name\":\"endpoint-a\"}'" }) } }] },
