406→test("REPRO: an echo among later arrivals must be caught, not only at the first one", () => {
407→  // The first arrival is a genuine other source; the second is the model's
408→  // own curl echoed back. Checking echoes only at the first arrival lets the
409→  // second count as a delivery of whichever asset the result happens to name.
410→  const requests = [req([
411→    { role: "system", content: "you are an agent" },
412→    { role: "tool", tool_call_id: "c0", content: "  1→notes … 47318 …" },
413→    { role: "assistant", content: null, tool_calls: [{ id: "c1", function: { name: "Bash", arguments: JSON.stringify({ command: "curl http://127.0.0.1:47318/skill-bridge/v3/skill/search" }) } }] },
414→    { role: "tool", tool_call_id: "c1", content: 'Command: curl http://127.0.0.1:47318/…\n{"data":{"skill_id":"skl-ok","items":[]}}' },
415→    { role: "assistant", content: "done" },
416→  ])];
417→  const attributionOf = (pos, entry, token) => {
418→    if (pos.index === 1) return { asset_id: null, path: "/tmp/notes.md" };
