383→test("REPRO: an earlier arrival from elsewhere must not hide a later real read of the asset", () => {
384→  // Both arrivals precede the operation. Taking only the first one lets a
385→  // knowledge file at m1 mask a genuine /skill/get at m3, and the verdict
386→  // then rests on "content arrived from somewhere" — which would hand out
387→  // the same true positive even if the real read had never happened.
388→  const requests = [req([
389→    { role: "system", content: "you are an agent" },
390→    { role: "tool", tool_call_id: "c0", content: "  1→SOP notes … 10.244.7.19:8096 …" },
391→    { role: "assistant", content: null, tool_calls: [{ id: "c1", function: { name: "Bash", arguments: JSON.stringify({ command: "curl .../skill/get" }) } }] },
392→    { role: "tool", tool_call_id: "c1", content: '{"data":{"skill_id":"skl-hidden","content":"reach it at 10.244.7.19:8096"}}' },
393→    { role: "assistant", content: "probing" },
394→  ])];
395→  const attributionOf = (pos, entry, token) => {
396→    if (pos.index === 1) return { asset_id: null, path: "/tmp/sop.md" };
397→    return attributionFromCapture(requests)(pos, entry, token);
398→  };
399→  const a = auditDelivery(requests, TOKENS, { operation: { request: 0, index: 4 }, coverageAsserted: true, attributionOf });
400→  assert.equal(a.assets["skl-hidden"].verdict, "delivered");
401→  // …and the other arrival is still on the record, not thrown away.
402→  const f = a.assets["skl-hidden"].findings[0];
403→  assert.ok(f.arrivals.length >= 2, "both arrivals are kept");
404→});
405→
406→test("REPRO: an echo among later arrivals must be caught, not only at the first one", () => {
407→  // The first arrival is a genuine other source; the second is the model's
408→  // own curl echoed back. Checking echoes only at the first arrival lets the
409→  // second count as a delivery of whichever asset the result happens to name.
410→  const requests = [req([
411→    { role: "system", content: "you are an agent" },
412→    { role: "tool", tool_call_id: "c0", content: "  1→notes … 47318 …" },
413→    { role: "assistant", content: null, tool_calls: [{ id: "c1", function: { name: "Bash", arguments: JSON.stringify({ command: "curl http://127.0.0.1:47318/skill-bridge/v3/skill/search" }) } }] },
414→    { role: "tool", tool_call_id: "c1", content: 'Command: curl http://127.0.0.1:47318/…\n{"data":{"skill_id":"skl-ok","items":[]}}' },
415→    { role: "assistant", content: "done" },
416→  ])];
417→  const attributionOf = (pos, entry, token) => {
418→    if (pos.index === 1) return { asset_id: null, path: "/tmp/notes.md" };
419→    return attributionFromCapture(requests)(pos, entry, token);
420→  };
421→  const a = auditDelivery(requests, TOKENS, { operation: { request: 0, index: 4 }, coverageAsserted: true, attributionOf });
422→  // The echo must not promote this to `delivered`.
423→  assert.equal(a.assets["skl-ok"].verdict, "delivered_from_other_source");
424→});
425→
426→test("REPRO: a token broken up by an FTS snippet is still the token", () => {
427→  // Real shape, from a search result in 20260905T153518Z-gate-off: FTS5
428→  // splits on punctuation and pads with spaces, so `10.244.7.19` arrives as
429→  // `10.244 . 7.19`. Matching a contiguous substring misses it — and missing
430→  // an arrival is the dangerous direction: a leak then reads as not
431→  // delivered, which the calibration files as a true negative.
432→  const snippet = 'Command: curl .../skill/search\n{"items":[{"skill_id":"skl-hidden","snippet":"…to   the   <mark>bridge</mark>   at : \\n \\n         <mark>http</mark> : / / 10.244 . 7.19 : 8096 / <mark>skill</mark> - <mark>bridge</mark> / v3 / <mark>skill</mark> / search \\n \\n Required…"}]}';
433→  const requests = [req([
434→    { role: "system", content: "you are an agent" },
435→    { role: "assistant", content: null, tool_calls: [{ id: "c1", function: { name: "Bash", arguments: JSON.stringify({ command: "curl .../skill/search -d '{\"query\":\"bridge\"}'" }) } }] },
436→    { role: "tool", tool_call_id: "c1", content: snippet },
437→    { role: "assistant", content: "the snippets document 10.244.7.19:8096" },
438→    { role: "assistant", content: null, tool_calls: [{ id: "c2", function: { name: "Bash", arguments: JSON.stringify({ command: "curl http://10.244.7.19:8096/…" }) } }] },
439→  ])];
440→  const a = auditDelivery(requests, TOKENS, { operation: { request: 0, index: 4 }, coverageAsserted: true,
441→    attributionOf: attributionFromCapture(requests) });
442→  assert.equal(a.assets["skl-hidden"].verdict, "delivered");
443→  // and it says the match was only found after normalising whitespace
444→  assert.match(a.assets["skl-hidden"].findings[0].arrivals[0].why ?? "", /./);
445→});
446→
447→test("normalising whitespace must not glue unrelated text into a token", () => {
448→  // `10.244` at the end of one line and `7.19` at the start of the next are
449→  // not necessarily one address, so the match is reported as normalised
450→  // rather than exact and the reader can tell them apart.
451→  assert.equal(containsToken("plain 10.244.7.19 here", "10.244.7.19").mode, "exact");
452→  assert.equal(containsToken("10.244 . 7.19", "10.244.7.19").mode, "whitespace_normalised");
453→  assert.equal(containsToken("nothing like it", "10.244.7.19").mode, null);
454→});
455→
456→test("REPRO: echoes must leave `judged` too, or the verdict names the wrong thing", () => {
457→  // Every arrival is an echo of the model's own command, and they sit after
458→  // the operation. `inTime` empties, the echoes-only branch short-circuits
459→  // on `inTime.length`, and the verdict falls through to after_operation —
460→  // "it arrived, just late" — pointing at an echo. Nothing arrived at all.
461→  const requests = [req([
462→    { role: "system", content: "you are an agent" },
463→    { role: "assistant", content: "from what I know the address is 10.244.7.19:8096" },
464→    { role: "assistant", content: null, tool_calls: [{ id: "c1", function: { name: "Bash", arguments: JSON.stringify({ command: "curl http://10.244.7.19:8096/x" }) } }] },
465→    { role: "tool", tool_call_id: "c1", content: "Command: curl http://10.244.7.19:8096/x\ntimed out" },
466→  ])];
467→  const a = auditDelivery(requests, TOKENS, { operation: { request: 0, index: 2 }, coverageAsserted: true,
468→    attributionOf: attributionFromCapture(requests) });
469→  // It came back as input, so it is an echo rather than "never seen"; either
470→  // way nothing reached the model, which is what the verdict has to convey.
471→  assert.equal(a.assets["skl-hidden"].verdict, "model_echo");
472→  assert.match(a.assets["skl-hidden"].findings[0].why, /nothing reached the model/);
473→});
474→

freshness.description:
Filter search results by time range. Supports d[N], m[N], and y[N] for the last N calendar days, months, and years:
- d[N]: N is an integer from 1 to 30;
- m[N]: N is an integer from 1 to 12;
- y[N]: N is an integer from 1 to 5.

N may be omitted and defaults to 1. The current partial calendar unit counts as 1. For example, d1 means today, m1 means the current month to date, and y1 means the current year to date. Omit this parameter to disable time filtering.

